// Dipanggil setiap ada data baru dari MQTT (iot/sensor)
var data = msg.payload;
if (typeof data !== 'object' || data === null) { return null; }
data.received = new Date().toISOString();

// Data terakhir tetap di flow context (untuk GET /api/suhu)
flow.set('lastSensor', data);

// Batas suhu (default 30 C, bisa diubah lewat PUT /api/threshold)
var th = flow.get('threshold');
if (th === undefined || th === null) { th = 30; flow.set('threshold', th); }

// Output 1: log ke debug
var logMsg = { payload: data };

// Output 2: simpan ke SQLite (prepared statement)
var dbMsg = { params: {
    $suhu: data.suhu,
    $kelembaban: data.kelembaban,
    $timestamp: data.timestamp,
    $received: data.received
} };

// Output 3: broadcast ke dashboard lewat WebSocket
var wsMsg = { payload: { type: 'sensor', data: data, threshold: th } };

// Output 4: notifikasi jika suhu melewati batas (maksimal 1x per 10 detik)
var alertMsg = null;
if (data.suhu > th) {
    var now = Date.now();
    var last = flow.get('lastAlertAt') || 0;
    if (now - last >= 10000) {
        flow.set('lastAlertAt', now);
        alertMsg = {
            topic: 'iot/alert',
            payload: {
                type: 'alert',
                suhu: data.suhu,
                batas: th,
                message: 'Suhu ' + data.suhu + ' C melewati batas ' + th + ' C',
                time: data.received
            }
        };
        node.warn(alertMsg.payload.message);
    }
}

return [logMsg, dbMsg, wsMsg, alertMsg];

// Autentikasi API key + routing ke endpoint
var API_KEY = env.get('IOT_API_KEY') || 'iot-api-key-2026';
var key = msg.req.headers['x-api-key'];
var path = msg.req.path.replace(/\/+$/, '');
var method = msg.req.method.toUpperCase();

msg.headers = {'Access-Control-Allow-Origin': '*'};

if (key !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    return [msg, null, null, null, null, null];
}

var out = [null, null, null, null, null, null];
if (method === 'GET' && path === '/api/suhu') out[1] = msg;
else if (method === 'GET' && path === '/api/history') out[2] = msg;
else if (method === 'POST' && path === '/api/kontrol') out[3] = msg;
else if (method === 'GET' && path === '/api/threshold') out[4] = msg;
else if (method === 'PUT' && path === '/api/threshold') out[5] = msg;
else {
    msg.statusCode = 404;
    msg.payload = {status: 'error', message: 'Endpoint tidak ditemukan'};
    out[0] = msg;
}
return out;

var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
msg.payload = {
    status: 'success',
    data: data,
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// msg.payload berisi hasil query SQLite (urut lama -> baru)
var rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = {
    status: 'success',
    count: rows.length,
    data: rows
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

var body = msg.payload;
if (!body || !body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

// Publish ke MQTT
var mqttMsg = {payload: body, topic: 'iot/kontrol'};

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, mqttMsg];

var th = flow.get('threshold');
if (th === undefined || th === null) { th = 30; }
msg.payload = {status: 'success', threshold: th};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

var body = msg.payload;
msg.headers = {'Access-Control-Allow-Origin': '*'};

var raw = (body && typeof body === 'object') ? body.max : undefined;
var max = Number(raw);

if (raw === undefined || raw === null || raw === '' || isNaN(max)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'field "max" (angka) wajib diisi'};
    return msg;
}
if (max < -40 || max > 80) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'max harus di antara -40 dan 80 (rentang DHT22)'};
    return msg;
}

flow.set('threshold', max);
flow.set('lastAlertAt', 0);

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', threshold: max};
return msg;

msg.statusCode = 500;
msg.payload = {status: 'error', message: 'Gagal membaca database: ' + (msg.error && msg.error.message ? msg.error.message : 'unknown')};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
